export function FaqSection() { useEffect(initConsolidatedFaq, []); return jsx('section', {"data-agimon-cleanup":"true","lang":"en","id":"faq","className":"agimon-faq","aria-labelledby":"faq-heading","dangerouslySetInnerHTML":{"__html":"\n  <div class=\"_container_1vxje_1 container\">\n    <div class=\"agimon-faq__inner\">\n      <header class=\"agimon-faq__header\">\n        <span class=\"_pillTag_1hr1d_1 pill-tag m white\">FAQ</span>\n        <h2 id=\"faq-heading\" data-faq-copy=\"faqIntroTitle\">A few things\nyou might be\nwondering.</h2>\n        <p><span data-faq-copy=\"faqContactPrompt\">Still have a question?</span><br><a href=\"https://agimon.io/#get-started\"><span data-faq-copy=\"faqContactLabel\">Let’s talk</span> <span aria-hidden=\"true\">↗</span></a></p>\n      </header>\n      <div class=\"agimon-faq__questions\"><details><summary><b data-faq-copy=\"faq1Question\">What is Agimon?</b><span aria-hidden=\"true\">+</span></summary><p data-faq-copy=\"faq1Answer\">Agimon brings your customer conversations, your team and your AI teammate into one chat app—with the tools to get the work done right there.</p></details>\n<details><summary><b data-faq-copy=\"faq2Question\">Do my customers need to switch apps?</b><span aria-hidden=\"true\">+</span></summary><p data-faq-copy=\"faq2Answer\">No. Your customers keep using WhatsApp, Instagram, email and the other channels you connect. Your team handles those conversations together in Agimon.</p></details>\n<details><summary><b data-faq-copy=\"faq3Question\">What can my Agimon actually do?</b><span aria-hidden=\"true\">+</span></summary><p data-faq-copy=\"faq3Answer\">Answer questions, follow up with customers, book appointments, check stock, run campaigns and manage tasks. Your Agimon uses the conversations, tools and data in your workspace to help get the work done.</p></details>\n<details><summary><b data-faq-copy=\"faq8Question\">Can my Agimon work across conversations?</b><span aria-hidden=\"true\">+</span></summary><p data-faq-copy=\"faq8Answer\">Yes. Your Agimon can draw on the conversations, tools and data it has access to across your workspace. Ask which customers need a follow-up, find information across chats, or turn business activity into useful summaries and next steps.</p></details>\n<details><summary><b data-faq-copy=\"faq4Question\">Does my team stay in control?</b><span aria-hidden=\"true\">+</span></summary><p data-faq-copy=\"faq4Answer\">Yes. Your team and your Agimon share the same conversations and tools. You can step in, reply and do the work directly, while deciding what your Agimon can access and handle.</p></details>\n<details><summary><b data-faq-copy=\"faq7Question\">Can I use my own AI tools?</b><span aria-hidden=\"true\">+</span></summary><p data-faq-copy=\"faq7Answer\">Yes. Work with your Agimon, connect your own AI tools, or use both. MCP lets compatible AI tools access your workspace’s conversations, tools and data. You can also bring your own key to use Codex inside your Agimon group chats.</p></details>\n<details><summary><b data-faq-copy=\"faq5Question\">Is Agimon for my kind of business?</b><span aria-hidden=\"true\">+</span></summary><p data-faq-copy=\"faq5Answer\">Yes. Agimon works for businesses of every kind. Bring your customer conversations, team, tools and data together, and shape the workspace around the way you work.</p></details>\n<details id=\"pricing-answer\"><summary><b data-faq-copy=\"faq9Question\">How much does Agimon cost?</b><span aria-hidden=\"true\">+</span></summary><p data-faq-copy=\"faq9Answer\">Plans start at US$39 per month. Let’s talk about your team and the setup you need.</p></details>\n<details id=\"getting-started-answer\"><summary><b data-faq-copy=\"faq6Question\">How do we get started?</b><span aria-hidden=\"true\">+</span></summary><p data-faq-copy=\"faq6Answer\"><a href=\"https://agimon.io/#get-started\">Get a demo</a> to see Agimon in action. We’ll walk through your business, show you how your team and your Agimon can work together, and help you get started.</p></details>\n<details id=\"founders-answer\"><summary><b data-faq-copy=\"faqFoundersQuestion\">Who’s behind Agimon?</b><span aria-hidden=\"true\">+</span></summary><p data-faq-copy=\"faqFoundersAnswer\">Four friends. Over 30 years of friendship. Building Agimon with love, for you.</p><ul class=\"agimon-founders\"><li><a class=\"agimon-founder\" href=\"https://www.linkedin.com/in/manologr/\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Manolo Gutiérrez — LinkedIn\"><img src=\"/assets/founders/manolo-gutierrez.png\" width=\"80\" height=\"80\" loading=\"lazy\" decoding=\"async\" alt=\"\"><span class=\"agimon-founder-name\" dir=\"ltr\">Manolo<br>Gutiérrez</span></a></li><li><a class=\"agimon-founder\" href=\"https://www.linkedin.com/in/eugeniopadilla/\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Eugenio Padilla — LinkedIn\"><img src=\"/assets/founders/eugenio-padilla.jpg\" width=\"80\" height=\"80\" loading=\"lazy\" decoding=\"async\" alt=\"\"><span class=\"agimon-founder-name\" dir=\"ltr\">Eugenio<br>Padilla</span></a></li><li><a class=\"agimon-founder\" href=\"https://linkedin.com/in/reyesjorge\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Jorge Reyes — LinkedIn\"><img src=\"/assets/founders/jorge-reyes.png\" width=\"80\" height=\"80\" loading=\"lazy\" decoding=\"async\" alt=\"\"><span class=\"agimon-founder-name\" dir=\"ltr\">Jorge<br>Reyes</span></a></li><li><a class=\"agimon-founder\" href=\"https://linkedin.com/in/andresmtzca\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Andres Martinez — LinkedIn\"><img src=\"/assets/founders/andres-martinez.jpg\" width=\"80\" height=\"80\" loading=\"lazy\" decoding=\"async\" alt=\"\"><span class=\"agimon-founder-name\" dir=\"ltr\">Andres<br>Martinez</span></a></li></ul></details></div>\n    </div>\n  </div>\n"}}); }
